head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70207";
scwin.disclsAlertMsg = null;
scwin.disclsCellphoneAhthErr = null;
scwin.discls_minute = 4;
scwin.discls_second = 59;
scwin.discls_timer = undefined;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — kclicUsrTpId

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.disclsAlertMsg = $c.util.getComponent('disclsAlertMsg');
        scwin.disclsCellphoneAhthErr = $c.util.getComponent('disclsCellphoneAhthErr');
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods70207.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_kclicUsrTpId", fn: function(){ return ((dma_pageContext.get("kclicUsrTpId") ?? "") === 'LIST_CORP_DISCLS'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_sPw", fn: function () { return String(String((dma_pageContext.get("sPw") ?? ""))); } },
        { childId: "ipt_sPwConfirm", fn: function () { return String(String((dma_pageContext.get("sPwConfirm") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.alertDiscls("인증번호가 발송되었습니다.");
        scwin.startTimer2();
        (document.disclsConfirm || { elements: [] }).action = "/combasinfo/comOvrvw.do?method=disclsConfirmInputPop&confrimChk=ok";
        const p = {}; p["returnValue"] = $c.util.getComponent("ipt_returnValue").getValue(); p["sPw"] = $c.util.getComponent("ipt_sPw").getValue(); p["sPwConfirm"] = $c.util.getComponent("ipt_sPwConfirm").getValue(); p["chrgTpCd"] = $c.util.getComponent("dma_closeCellphoneAhthReq").get("chrgTpCd"); p["phonePw"] = $c.util.getComponent("ipt_phonePw").getValue(); $c.win.setPageFrameSrc($c.win.getFrame(), '/jldods70207/jldods70207.xml', p);
        scwin.alertDiscls("휴대폰 인증에 실패하였습니다.\n다시 시도하십시오.");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70207.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 4개다(comovrvw#disclsconfirminputpop vs comovrvw#excelpop vs comovrvw#cellphoneahthsend vs comovrvw#disclspasswordchange) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
