 */
scwin.btn_closeCellphoneAhth_onclick = async function(e){
    try {
        await scwin.closeCellphoneAhth()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70207.btn_closeCellphoneAhth_onclick' }); }
};

/**
 * @method
 * @name btn_closeCellphoneAhth_2_onclick
 * @description 「레이어닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
