    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70207.btn_closeCellphoneAhth_2_onclick' }); }
};

/**
 * @method
 * @name ipt_userSend_onclick
 * @description 「인증번호 받기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_userSend_onclick = async function(e){
    try {
        await scwin.cellphoneAhthSend()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70207.ipt_userSend_onclick' }); }
};

/**
