scwin.btn_disclsNumberChange_onclick = function(e){
    try {
        scwin.disclsNumberChange()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70207.btn_disclsNumberChange_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description 「취소」 클릭 이벤트
