 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70207.btn_window_onclick' }); }
};

/**
 * @method
 * @name btn_window_2_onclick
 * @description 「레이어닫기」 클릭 이벤트
