///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_closeCellphoneAhth
 * @description close Cellphone Ahth 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_closeCellphoneAhth = async function () {
    const sbmOptions = {
        id: "tx_closeCellphoneAhth",
        method: "post",
        action: "/combasinfo/comOvrvw.do?method=disclsConfirmAdjPop",
        ref: "dma_closeCellphoneAhthReq",
        target: "dlt_disclsUserList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_cellphoneAhthSend
 * @description cellphone Ahth Send 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_cellphoneAhthSend = async function () {
    const sbmOptions = {
        id: "tx_cellphoneAhthSend",
        method: "post",
        action: "/combasinfo/comOvrvw.do?method=cellphoneAhthSend",
        ref: "dma_cellphoneAhthSendReq",
        target: "dlt_disclsUserList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_disclsNumberChange
 * @description discls Number Change 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_disclsNumberChange = async function () {
    const sbmOptions = {
        id: "tx_disclsNumberChange",
        method: "post",
        action: "/combasinfo/comOvrvw.do?method=disclsPasswordChange",
        ref: "dma_disclsNumberChangeReq",
        target: "dlt_disclsUserList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name startTimer2
 * @description start Timer2 처리
 * @returns {void}
 * @hidden N
 */
scwin.startTimer2 = function () {
    scwin.discls_timer = setInterval(function() {
            if (scwin.discls_second === 0) {
                scwin.discls_minute = scwin.discls_minute - 1;
                scwin.discls_second = 60;
            }
            scwin.discls_second = scwin.discls_second - 1;
            if (scwin.discls_minute <= 0 && scwin.discls_second <= 0) {
                clearInterval(scwin.discls_timer);
                scwin.alertCellphoneAhth("휴대폰 인증번호 입력시간(5분)이 초과되었습니다.\n재시도 하십시오.");
            }
            areaSessionTimer2.setLabel(scwin.discls_minute + ":" + ((scwin.discls_second + "").length === 1 ? '0' + scwin.discls_second : scwin.discls_second));
        }, 1000);
};

/**
 * @method
 * @name resizeWindow
 * @description resize Window 처리
 * @param {*} win win
 * @returns {void}
 * @hidden N
 */
scwin.resizeWindow = function (win) {
    win.resizeTo(770, 550);
    win.resizeTo(770, 600);
    win.resizeTo(770, 650);
    win.resizeTo(770, 500);
};

/**
 * @method
 * @name alertDiscls
 * @description alert Discls 처리
 * @param {String} msg 항목명
 * @returns {void}
 * @hidden N
 */
scwin.alertDiscls = function (msg) {
    layerUI2('#layerUi');
    layerUI2('.layerUi');
    $('#txt_pAlertDisclsText')[0].innerText = msg;
    scwin.disclsAlertMsg.setStyle("display", "");
};

/**
 * @method
 * @name closeAlertDiscls
 * @description close Alert Discls 처리
 * @returns {void}
 * @hidden N
 */
scwin.closeAlertDiscls = function () {
    scwin.disclsAlertMsg.setStyle("display", "none");
};

/**
 * @method
 * @name alertCellphoneAhth
 * @description alert Cellphone Ahth 처리
 * @param {String} msg 항목명
 * @returns {void}
 * @hidden N
 */
scwin.alertCellphoneAhth = function (msg) {
    layerUI2('#layerUi');
    layerUI2('.layerUi');
    $('#txt_pCellphoneAhthText')[0].innerText = msg;
    scwin.disclsCellphoneAhthErr.setStyle("display", "");
};

/**
 * @method
 * @name closeCellphoneAhth
 * @description close Cellphone Ahth 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.closeCellphoneAhth = async function () {
    scwin.disclsCellphoneAhthErr.setStyle("display", "none");
    (document.disclsConfirm || { elements: [] }).action = "/combasinfo/comOvrvw.do?method=disclsConfirmAdjPop";
    await scwin.tx_closeCellphoneAhth();
};

/**
 * @method
 * @name cellphoneAhthSend
 * @description cellphone Ahth Send 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cellphoneAhthSend = async function () {
    if (scwin.checkCellphoneNumber()) {
        (document.disclsConfirm || { elements: [] }).action = "/combasinfo/comOvrvw.do?method=cellphoneAhthSend";
        await scwin.tx_cellphoneAhthSend();
    }
};

/**
 * @method
 * @name checkCellphoneNumber
 * @description check Cellphone Number 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkCellphoneNumber = function () {
    let sVal = 'O';
    const checkVal = $('input:radio[name="chrgTpCd"]:checked').val();
    if (typeof checkVal === "undefined" || checkVal === "") {
        scwin.alertDiscls("인증받을 연락처를 선택하십시오.");
        sVal = 'X';
    }
    if (sVal === 'O') {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name disclsNumberChange
 * @description discls Number Change 처리
 * @returns {void}
 * @hidden N
 */
scwin.disclsNumberChange = function () {
    if ($('#ipt_sPw', $('#disclsConfirm')).val() === "") {
        scwin.alertDiscls("새 화면접근번호를 입력하십시오.");
        ($c.util.getComponent('ipt_sPw') && $c.util.getComponent('ipt_sPw').setFocus ? $c.util.getComponent('ipt_sPw').setFocus() : ($c.util.getComponent('ipt_sPw') && $c.util.getComponent('ipt_sPw').focus ? $c.util.getComponent('ipt_sPw').focus() : console.warn('[sdd] focus 대상 미해결: ipt_sPw')));
        return;
    }
    const sPw = $c.util.getComponent('ipt_sPw').getValue();
    if (sPw.length < 6) {
        scwin.alertDiscls("새 화면접근번호는 6자리 이상 입력하십시오.");
        ($c.util.getComponent('ipt_sPw') && $c.util.getComponent('ipt_sPw').setFocus ? $c.util.getComponent('ipt_sPw').setFocus() : ($c.util.getComponent('ipt_sPw') && $c.util.getComponent('ipt_sPw').focus ? $c.util.getComponent('ipt_sPw').focus() : console.warn('[sdd] focus 대상 미해결: ipt_sPw')));
        return;
    }
    if ($('#ipt_sPwConfirm', $('#disclsConfirm')).val() === "") {
        scwin.alertDiscls("새 화면접근번호확인을 입력하십시오.");
        ($c.util.getComponent('ipt_sPwConfirm') && $c.util.getComponent('ipt_sPwConfirm').setFocus ? $c.util.getComponent('ipt_sPwConfirm').setFocus() : ($c.util.getComponent('ipt_sPwConfirm') && $c.util.getComponent('ipt_sPwConfirm').focus ? $c.util.getComponent('ipt_sPwConfirm').focus() : console.warn('[sdd] focus 대상 미해결: ipt_sPwConfirm')));
        return;
    }
    const sPwConfirm = $c.util.getComponent('ipt_sPwConfirm').getValue();
    if (sPwConfirm.length < 6) {
        scwin.alertDiscls("새 화면접근번호확인은 6자리 이상 입력하십시오.");
        ($c.util.getComponent('ipt_sPwConfirm') && $c.util.getComponent('ipt_sPwConfirm').setFocus ? $c.util.getComponent('ipt_sPwConfirm').setFocus() : ($c.util.getComponent('ipt_sPwConfirm') && $c.util.getComponent('ipt_sPwConfirm').focus ? $c.util.getComponent('ipt_sPwConfirm').focus() : console.warn('[sdd] focus 대상 미해결: ipt_sPwConfirm')));
        return;
    }
    if ($('#ipt_sPw', $('#disclsConfirm')).val() !== $('#ipt_sPwConfirm', $('#disclsConfirm')).val()) {
        scwin.alertDiscls("새 화면접근번호가 일치하지 않습니다.");
        ($c.util.getComponent('ipt_sPwConfirm') && $c.util.getComponent('ipt_sPwConfirm').setFocus ? $c.util.getComponent('ipt_sPwConfirm').setFocus() : ($c.util.getComponent('ipt_sPwConfirm') && $c.util.getComponent('ipt_sPwConfirm').focus ? $c.util.getComponent('ipt_sPwConfirm').focus() : console.warn('[sdd] focus 대상 미해결: ipt_sPwConfirm')));
        return;
    }
    if (!scwin.checkCellphoneNumber()) {
        return;
    }
    scwin.alertDiscls("인증번호 받기를 선택하십시오.");
    return;
    const phonePw = $c.util.getComponent('ipt_phonePw').getValue();
    if ($('#ipt_phonePw', $('#disclsConfirm')).val() === "") {
        scwin.alertDiscls("휴대폰 인증번호를 입력하십시오.");
        ($c.util.getComponent('ipt_phonePw') && $c.util.getComponent('ipt_phonePw').setFocus ? $c.util.getComponent('ipt_phonePw').setFocus() : ($c.util.getComponent('ipt_phonePw') && $c.util.getComponent('ipt_phonePw').focus ? $c.util.getComponent('ipt_phonePw').focus() : console.warn('[sdd] focus 대상 미해결: ipt_phonePw')));
        return;
    }
    let returnValue = "";
    $.ajax({ type: "POST", url: "/combasinfo/comOvrvw.do", data: { method: "disclsPasswordChange", sPw: sPw, phonePw: phonePw }, success: async function(data) {
                returnValue = data.returnValue;
                if (returnValue === 'true') {
                    (document.disclsConfirm || { elements: [] }).action = "/combasinfo/comOvrvw.do?method=disclsConfirmInputPop&confrimChk=ok";
                    await scwin.tx_disclsNumberChange();
                } else {
                    scwin.alertDiscls("휴대폰 인증에 실패하였습니다.\n다시 시도하십시오.");
                }
                $c.util.getComponent('ipt_returnValue').setValue(returnValue);
            }, error: function(request, status, error) {
                void(error);
            }, complete: function() {

            } });
};
